arguments.new_str:
using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 breaking change: ZipArchiveEntry now respects the UTF-8 flag.
        // Legacy Java consumer reads filenames as Shift-JIS, so we must use
        // the ZipFile.Open overload with an explicit non-UTF8 encoding to
        // prevent the UTF-8 flag from being set in entry headers.
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create,
            Encoding.GetEncoding("shift_jis"));
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

